     6→
     7→// ─────────────────────────────────────────────────────────────────────────────
     8→// Utilities
     9→// ─────────────────────────────────────────────────────────────────────────────
    10→
    11→function describeCron(schedule) {
    12→  const parts = schedule.trim().split(/\s+/);
    13→  if (parts.length !== 5) return schedule;
    14→
    15→  const [minute, hour, dayOfMonth, month, dayOfWeek] = parts;
    16→
    17→  // Every N minutes
    18→  if (minute.startsWith('*/') && hour === '*' && dayOfMonth === '*' && month === '*' && dayOfWeek === '*') {
    19→    const n = parseInt(minute.slice(2), 10);
    20→    if (n === 1) return 'Every minute';
    21→    return `Every ${n} minutes`;
    22→  }
    23→
    24→  // Every N hours
    25→  if (hour.startsWith('*/') && dayOfMonth === '*' && month === '*' && dayOfWeek === '*') {
    26→    const n = parseInt(hour.slice(2), 10);
    27→    if (n === 1) return 'Every hour';
    28→    return `Every ${n} hours`;
    29→  }
    30→
    31→  // Specific time daily
    32→  if (minute !== '*' && hour !== '*' && !hour.includes('/') && !minute.includes('/') && dayOfMonth === '*' && month === '*' && dayOfWeek === '*') {
    33→    const h = parseInt(hour, 10);
    34→    const m = parseInt(minute, 10);
    35→    const period = h >= 12 ? 'PM' : 'AM';
    36→    const displayH = h === 0 ? 12 : h > 12 ? h - 12 : h;
    37→    return `Daily at ${displayH}:${String(m).padStart(2, '0')} ${period}`;
    38→  }
    39→
