     9→import { verifyApiKey } from '../lib/db/api-keys.js';
    10→import { getConfig } from '../lib/config.js';
    11→
    12→// Bot token — resolved from DB/env, can be overridden by /telegram/register
    13→let telegramBotToken = null;
    14→
    15→// Cached trigger firing function (initialized on first request)
    16→let _fireTriggers = null;
    17→
    18→function getTelegramBotToken() {
    19→  if (!telegramBotToken) {
    20→    telegramBotToken = getConfig('TELEGRAM_BOT_TOKEN') || null;
    21→  }
    22→  return telegramBotToken;
    23→}
    24→
    25→function getFireTriggers() {
    26→  if (!_fireTriggers) {
    27→    const result = loadTriggers();
    28→    _fireTriggers = result.fireTriggers;
    29→  }
    30→  return _fireTriggers;
    31→}
    32→
    33→// Routes that have their own authentication
    34→const PUBLIC_ROUTES = ['/telegram/webhook', '/github/webhook', '/vault-sync', '/ping'];
    35→
    36→/**
    37→ * Timing-safe string comparison.
    38→ * @param {string} a
    39→ * @param {string} b
    40→ * @returns {boolean}
    41→ */
    42→function safeCompare(a, b) {
    43→  if (!a || !b) return false;
    44→  const bufA = Buffer.from(a);
    45→  const bufB = Buffer.from(b);
    46→  if (bufA.length !== bufB.length) return false;
    47→  return timingSafeEqual(bufA, bufB);
    48→}
    49→
    50→/**
    51→ * Centralized auth gate for all API routes.
    52→ * Public routes pass through; everything else requires a valid API key from the database.
    53→ * @param {string} routePath - The route path
    54→ * @param {Request} request - The incoming request
    55→ * @returns {Response|null} - Error response or null if authorized
    56→ */
    57→function checkAuth(routePath, request) {
    58→  if (PUBLIC_ROUTES.includes(routePath)) return null;
    59→
    60→  const apiKey = request.headers.get('x-api-key');
    61→  if (!apiKey) {
    62→    return Response.json({ error: 'Unauthorized' }, { status: 401 });
    63→  }
    64→
    65→  const record = verifyApiKey(apiKey);
    66→  if (!record) {
    67→    return Response.json({ error: 'Unauthorized' }, { status: 401 });
    68→  }
    69→
    70→  return null;
    71→}
    72→
    73→/**
    74→ * Extract job ID from branch name (e.g., "job/abc123" -> "abc123")
    75→ */
    76→function extractJobId(branchName) {
    77→  if (!branchName || !branchName.startsWith('job/')) return null;
    78→  return branchName.slice(4);
    79→}
    80→
    81→// ─────────────────────────────────────────────────────────────────────────────
    82→// Route handlers
    83→// ─────────────────────────────────────────────────────────────────────────────
    84→
    85→async function handleWebhook(request) {
    86→  const body = await request.json();
    87→  const { job } = body;
    88→  if (!job) return Response.json({ error: 'Missing job field' }, { status: 400 });
    89→
    90→  try {
    91→    const result = await createJob(job);
    92→    return Response.json(result);
    93→  } catch (err) {
    94→    console.error(err);
    95→    return Response.json({ error: 'Failed to create job' }, { status: 500 });
    96→  }
    97→}
    98→
    99→async function handleTelegramRegister(request) {
   100→  const body = await request.json();
   101→  const { bot_token, webhook_url } = body;
   102→  if (!bot_token || !webhook_url) {
   103→    return Response.json({ error: 'Missing bot_token or webhook_url' }, { status: 400 });
   104→  }
   105→
   106→  try {
   107→    const result = await setWebhook(bot_token, webhook_url, getConfig('TELEGRAM_WEBHOOK_SECRET'));
   108→    telegramBotToken = bot_token;
   109→    return Response.json({ success: true, result });
   110→  } catch (err) {
   111→    console.error(err);
   112→    return Response.json({ error: 'Failed to register webhook' }, { status: 500 });
   113→  }
   114→}
   115→
   116→async function handleTelegramWebhook(request) {
   117→  const botToken = getTelegramBotToken();
   118→  if (!botToken) return Response.json({ ok: true });
   119→
   120→  const adapter = getTelegramAdapter(botToken);
   121→  const normalized = await adapter.receive(request);
   122→  if (!normalized) return Response.json({ ok: true });
   123→
   124→  // Process message asynchronously (don't block the webhook response)
   125→  processChannelMessage(adapter, normalized).catch((err) => {
   126→    console.error('Failed to process message:', err);
   127→  });
   128→
   129→  return Response.json({ ok: true });
   130→}
   131→
   132→/**
   133→ * Process a normalized message through the AI layer with channel UX.
   134→ * Message persistence is handled centrally by the AI layer.
   135→ */
   136→async function processChannelMessage(adapter, normalized) {
   137→  await adapter.acknowledge(normalized.metadata);
   138→  const stopIndicator = adapter.startProcessingIndicator(normalized.metadata);
   139→
   140→  try {
   141→    const response = await chat(
   142→      normalized.threadId,
   143→      normalized.text,
   144→      normalized.attachments,
   145→      { userId: 'telegram', chatTitle: 'Telegram' }
   146→    );
   147→    await adapter.sendResponse(normalized.threadId, response, normalized.metadata);
   148→  } catch (err) {
   149→    console.error('Failed to process message with AI:', err);
   150→    await adapter
   151→      .sendResponse(
   152→        normalized.threadId,
   153→        'Sorry, I encountered an error processing your message.',
   154→        normalized.metadata
   155→      )
   156→      .catch(() => {});
   157→  } finally {
   158→    stopIndicator();
   159→  }
   160→}
   161→
   162→async function handleGithubWebhook(request) {
   163→  const GH_WEBHOOK_SECRET = getConfig('GH_WEBHOOK_SECRET');
   164→
   165→  // Validate webhook secret (timing-safe, required)
   166→  if (!GH_WEBHOOK_SECRET || !safeCompare(request.headers.get('x-github-webhook-secret-token'), GH_WEBHOOK_SECRET)) {
   167→    return Response.json({ error: 'Unauthorized' }, { status: 401 });
   168→  }
   169→
   170→  const payload = await request.json();
   171→  const jobId = payload.job_id || extractJobId(payload.branch);
   172→  if (!jobId) return Response.json({ ok: true, skipped: true, reason: 'not a job' });
   173→
   174→  try {
   175→    // Fetch log from repo via API (no longer sent in payload)
   176→    let log = payload.log || '';
   177→    if (!log) {
   178→      log = await fetchJobLog(jobId, payload.commit_sha);
   179→    }
   180→
   181→    const results = {
   182→      job: payload.job || '',
   183→      pr_url: payload.pr_url || payload.run_url || '',
   184→      run_url: payload.run_url || '',
   185→      status: payload.status || '',
   186→      merge_result: payload.merge_result || '',
   187→      log,
   188→      changed_files: payload.changed_files || [],
   189→      commit_message: payload.commit_message || '',
   190→    };
   191→
   192→    const message = await summarizeJob(results);
   193→    await createNotification(message, payload);
   194→
   195→    console.log(`Notification saved for job ${jobId.slice(0, 8)}`);
   196→
   197→    return Response.json({ ok: true, notified: true });
   198→  } catch (err) {
   199→    console.error('Failed to process GitHub webhook:', err);
   200→    return Response.json({ error: 'Failed to process webhook' }, { status: 500 });
   201→  }
   202→}
   203→
   204→// System files in job logs — NOT synced to vault
   205→const VAULT_SKIP_FILES = new Set([
   206→  'claude-session.jsonl', 'claude-stderr.log', 'system-prompt.md', 'job.config.json',
   207→]);
   208→
   209→/**
   210→ * Sync job output files from GitHub to Obsidian vault.
   211→ * Reads .md outputs from the job log directory and writes to vault via REST API.
   212→ * Vault path: checks for `vault-path:` in YAML frontmatter, else `05-Agent-Outputs/{filename}`.
   213→ */
   214→async function handleVaultSync(request) {
   215→  // Auth: validate WEBHOOK_SECRET (same pattern as GitHub webhook)
   216→  const WEBHOOK_SECRET = getConfig('WEBHOOK_SECRET');
   217→  if (!WEBHOOK_SECRET || !safeCompare(request.headers.get('x-webhook-secret'), WEBHOOK_SECRET)) {
   218→    return Response.json({ error: 'Unauthorized' }, { status: 401 });
   219→  }
   220→
   221→  const body = await request.json();
   222→  const { job_id, commit_sha } = body;
   223→
   224→  if (!job_id || !commit_sha) {
   225→    return Response.json({ error: 'Missing job_id or commit_sha' }, { status: 400 });
   226→  }
   227→
   228→  const { GH_OWNER, GH_REPO } = process.env;
   229→  const OBSIDIAN_HOST = getConfig('OBSIDIAN_HOST');
   230→  const OBSIDIAN_API_KEY = getConfig('OBSIDIAN_API_KEY');
   231→
   232→  if (!OBSIDIAN_HOST || !OBSIDIAN_API_KEY) {
   233→    return Response.json({ error: 'Obsidian not configured' }, { status: 500 });
   234→  }
   235→
   236→  try {
   237→    const files = await githubApi(
   238→      `/repos/${GH_OWNER}/${GH_REPO}/contents/logs/${job_id}?ref=${encodeURIComponent(commit_sha)}`
   239→    );
   240→
   241→    if (!Array.isArray(files)) {
   242→      return Response.json({ ok: true, synced: 0, reason: 'no log directory' });
   243→    }
   244→
   245→    const outputFiles = files.filter(f => f.name.endsWith('.md') && !VAULT_SKIP_FILES.has(f.name));
   246→    if (outputFiles.length === 0) {
   247→      return Response.json({ ok: true, synced: 0, reason: 'no output files' });
   248→    }
   249→
   250→    const synced = [];
   251→    for (const file of outputFiles) {
   252→      const fileData = await githubApi(
   253→        `/repos/${GH_OWNER}/${GH_REPO}/contents/logs/${job_id}/${file.name}?ref=${encodeURIComponent(commit_sha)}`
   254→      );
   255→      const content = Buffer.from(fileData.content, 'base64').toString('utf-8');
   256→
   257→      // Check frontmatter for explicit vault path
   258→      let vaultPath = `05-Agent-Outputs/${file.name}`;
   259→      const match = content.match(/^---\n[\s\S]*?vault-path:\s*(.+)\n[\s\S]*?---/);
   260→      if (match) vaultPath = match[1].trim();
   261→
   262→      const res = await fetch(`${OBSIDIAN_HOST}/vault/${vaultPath}`, {
   263→        method: 'PUT',
   264→        headers: { 'Authorization': `Bearer ${OBSIDIAN_API_KEY}`, 'Content-Type': 'text/markdown' },
   265→        body: content,
   266→      });
   267→
   268→      if (res.ok || res.status === 204) {
   269→        synced.push({ file: file.name, vault_path: vaultPath });
   270→        console.log(`[vault-sync] ${file.name} → ${vaultPath}`);
   271→      } else {
   272→        console.error(`[vault-sync] Failed: ${vaultPath} HTTP ${res.status}`);
   273→      }
   274→    }
   275→
   276→    console.log(`[vault-sync] Job ${job_id.slice(0, 8)}: ${synced.length}/${outputFiles.length} files`);
   277→    return Response.json({ ok: true, synced: synced.length, files: synced });
   278→  } catch (err) {
   279→    console.error('[vault-sync] Error:', err.message);
   280→    return Response.json({ error: 'Vault sync failed' }, { status: 500 });
   281→  }
   282→}
   283→
   284→async function handleJobStatus(request) {
   285→  try {
   286→    const url = new URL(request.url);
   287→    const jobId = url.searchParams.get('job_id');
   288→    const result = await getJobStatus(jobId);
   289→    return Response.json(result);
   290→  } catch (err) {
   291→    console.error('Failed to get job status:', err);
   292→    return Response.json({ error: 'Failed to get job status' }, { status: 500 });
   293→  }
   294→}
   295→
   296→// ─────────────────────────────────────────────────────────────────────────────
   297→// Next.js Route Handlers (catch-all)
   298→// ─────────────────────────────────────────────────────────────────────────────
   299→
   300→async function POST(request) {
   301→  const url = new URL(request.url);
   302→  const routePath = url.pathname.replace(/^\/api/, '');
   303→
   304→  // Auth check
   305→  const authError = checkAuth(routePath, request);
   306→  if (authError) return authError;
   307→
   308→  // Fire triggers (non-blocking)
   309→  try {
   310→    const fireTriggers = getFireTriggers();
   311→    // Clone request to read body for triggers without consuming it for the handler
   312→    const clonedRequest = request.clone();
   313→    const body = await clonedRequest.json().catch(() => ({}));
   314→    const query = Object.fromEntries(url.searchParams);
   315→    const headers = Object.fromEntries(request.headers);
   316→    fireTriggers(routePath, body, query, headers);
   317→  } catch (e) {
   318→    // Trigger errors are non-fatal
   319→  }
   320→
   321→  // Cluster role webhooks
   322→  const clusterMatch = routePath.match(/^\/cluster\/([a-f0-9-]+)\/role\/([a-f0-9-]+)\/webhook$/);
   323→  if (clusterMatch) {
   324→    const { handleClusterWebhook } = await import('../lib/cluster/runtime.js');
   325→    return handleClusterWebhook(clusterMatch[1], clusterMatch[2], request);
   326→  }
   327→
   328→  // Route to handler
   329→  switch (routePath) {
   330→    case '/create-job':          return handleWebhook(request);
   331→    case '/vault-sync':          return handleVaultSync(request);
   332→    case '/telegram/webhook':   return handleTelegramWebhook(request);
   333→    case '/telegram/register':  return handleTelegramRegister(request);
   334→    case '/github/webhook':     return handleGithubWebhook(request);
   335→    default:                    return Response.json({ error: 'Not found' }, { status: 404 });
   336→  }
