    console.log('[picklist-daytime] No picklist generated.');
    process.exit(0);
  }

  console.log(`[picklist-daytime] Auto-batched picklist ${picklist.id.slice(0, 8)} — ${picklist.orderCount} orders.`);
  process.exit(0);
}).catch((err) => {
  console.error('[picklist-daytime] Error:', err.message);
  process.exit(1);
});

